test('vatSummary includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []).value;
  const partial = recordPayment(issued, { amount: 1000, date: '2026-10-10' }).value;
  const result = vatSummary([partial]);
  assert.equal(result.length, 1);
});

test('vatSummary includes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []).value;
  const due = balanceDue(issued);
  const paid = recordPayment(issued, { amount: due, date: '2026-10-10' }).value;
  const result = vatSummary([paid]);
  assert.equal(result.length, 1);
});

test('vatSummary groups by VAT rate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'PEN', qty: 50 }],
  });
  const issued2 = issueInvoice(inv2.value, []).value;

  const result = vatSummary([issued1, issued2]);
  assert.equal(result.length, 2);
  assert.ok(result.some((r) => r.rate === 21));
  assert.ok(result.some((r) => r.rate === 9));
});

test('vatSummary sums base correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []).value;
  const result = vatSummary([issued]);
  const totals = invoiceTotals(issued);
  assert.equal(result[0].base, totals.subtotal - totals.discount);
});

test('vatSummary sums VAT correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []).value;
  const result = vatSummary([issued]);
  const totals = invoiceTotals(issued);
  assert.equal(result[0].vat, totals.vat);
});

test('vatSummary sorts by rate descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
